301	  void initScheduler(Configuration configuration) throws
302	      IOException, YarnException {
303	    writeLock.lock();
304	    try {
305	      String confProviderStr = configuration.get(
306	          YarnConfiguration.SCHEDULER_CONFIGURATION_STORE_CLASS,
307	          YarnConfiguration.DEFAULT_CONFIGURATION_STORE);
308	      switch (confProviderStr) {
309	      case YarnConfiguration.FILE_CONFIGURATION_STORE:
310	        this.csConfProvider =
311	            new FileBasedCSConfigurationProvider(rmContext);
312	        break;
313	      case YarnConfiguration.MEMORY_CONFIGURATION_STORE:
314	      case YarnConfiguration.LEVELDB_CONFIGURATION_STORE:
315	      case YarnConfiguration.ZK_CONFIGURATION_STORE:
316	      case YarnConfiguration.FS_CONFIGURATION_STORE:
317	        this.csConfProvider = new MutableCSConfigurationProvider(rmContext);
318	        break;
319	      default:
320	        throw new IOException("Invalid configuration store class: " +
321	            confProviderStr);
322	      }
323	      this.csConfProvider.init(configuration);
324	      this.conf = this.csConfProvider.loadConfiguration(configuration);
325	      validateConf(this.conf);
326	      this.minimumAllocation = super.getMinimumAllocation();
327	      initMaximumResourceCapability(super.getMaximumAllocation());
328	      this.calculator = this.conf.getResourceCalculator();
329	      if (this.calculator instanceof DefaultResourceCalculator
330	          && ResourceUtils.getNumberOfKnownResourceTypes() > 2) {
331	        throw new YarnRuntimeException("RM uses DefaultResourceCalculator which"
332	            + " used only memory as resource-type but invalid resource-types"
333	            + " specified " + ResourceUtils.getResourceTypes() + ". Use"
334	            + " DominantResourceCalculator instead to make effective use of"
335	            + " these resource-types");
336	      }
337	      this.usePortForNodeName = this.conf.getUsePortForNodeName();
338	      this.applications = new ConcurrentHashMap<>();
339	      this.labelManager = rmContext.getNodeLabelManager();
340	      this.appPriorityACLManager = new AppPriorityACLsManager(conf);
341	      this.queueManager = new CapacitySchedulerQueueManager(yarnConf,
342	          this.labelManager, this.appPriorityACLManager);
343	      this.queueManager.setCapacitySchedulerContext(this);
344	
345	      this.workflowPriorityMappingsMgr = new WorkflowPriorityMappingsManager();
346	
347	      this.activitiesManager = new ActivitiesManager(rmContext);
348	      activitiesManager.init(conf);
349	      initializeQueues(this.conf);
350	      this.isLazyPreemptionEnabled = conf.getLazyPreemptionEnabled();
351	
352	      scheduleAsynchronously = this.conf.getScheduleAynschronously();
353	      asyncScheduleInterval = this.conf.getLong(ASYNC_SCHEDULER_INTERVAL,
354	          DEFAULT_ASYNC_SCHEDULER_INTERVAL);
355	
356	      this.assignMultipleEnabled = this.conf.getAssignMultipleEnabled();
357	      this.maxAssignPerHeartbeat = this.conf.getMaxAssignPerHeartbeat();
358	
359	      this.appShouldFailFast = CapacitySchedulerConfiguration.shouldAppFailFast(
360	          getConfig());
361	
362	      // number of threads for async scheduling
363	      int maxAsyncSchedulingThreads = this.conf.getInt(
364	          CapacitySchedulerConfiguration.SCHEDULE_ASYNCHRONOUSLY_MAXIMUM_THREAD,
365	          1);
366	      maxAsyncSchedulingThreads = Math.max(maxAsyncSchedulingThreads, 1);
367	
368	      if (scheduleAsynchronously) {
369	        asyncSchedulerThreads = new ArrayList<>();
370	        for (int i = 0; i < maxAsyncSchedulingThreads; i++) {
371	          asyncSchedulerThreads.add(new AsyncScheduleThread(this));
372	        }
373	        resourceCommitterService = new ResourceCommitterService(this);
374	        asyncMaxPendingBacklogs = this.conf.getInt(
375	            CapacitySchedulerConfiguration.
376	                SCHEDULE_ASYNCHRONOUSLY_MAXIMUM_PENDING_BACKLOGS,
377	            CapacitySchedulerConfiguration.
378	                DEFAULT_SCHEDULE_ASYNCHRONOUSLY_MAXIMUM_PENDING_BACKLOGS);
379	      }
380	
381	      // Setup how many containers we can allocate for each round
382	      offswitchPerHeartbeatLimit = this.conf.getOffSwitchPerHeartbeatLimit();
383	
384	      // Register CS specific multi-node policies to common MultiNodeManager
385	      // which will add to a MultiNodeSorter which gives a pre-sorted list of
386	      // nodes to scheduler's allocation.
387	      multiNodePlacementEnabled = this.conf.getMultiNodePlacementEnabled();
388	      if(rmContext.getMultiNodeSortingManager() != null) {
389	        rmContext.getMultiNodeSortingManager().registerMultiNodePolicyNames(
390	            multiNodePlacementEnabled,
391	            this.conf.getMultiNodePlacementPolicies());
392	      }
393	
394	      LOG.info("Initialized CapacityScheduler with " + "calculator="
395	          + getResourceCalculator().getClass() + ", " + "minimumAllocation="
396	          + getMinimumResourceCapability() + ", " + "maximumAllocation="
397	          + getMaximumResourceCapability() + ", " + "asynchronousScheduling="
398	          + scheduleAsynchronously + ", " + "asyncScheduleInterval="
399	          + asyncScheduleInterval + "ms" + ",multiNodePlacementEnabled="
400	          + multiNodePlacementEnabled + ", " + "assignMultipleEnabled="
401	          + assignMultipleEnabled + ", " + "maxAssignPerHeartbeat="
402	          + maxAssignPerHeartbeat + ", " + "offswitchPerHeartbeatLimit="
403	          + offswitchPerHeartbeatLimit);
404	    } finally {
405	      writeLock.unlock();
406	    }
