444	    writeLock.lock();
445	    try {
446	      this.activitiesManager.stop();
447	      if (scheduleAsynchronously && asyncSchedulerThreads != null) {
448	        for (Thread t : asyncSchedulerThreads) {
449	          t.interrupt();
450	          t.join(THREAD_JOIN_TIMEOUT_MS);
451	        }
452	        resourceCommitterService.interrupt();
453	        resourceCommitterService.join(THREAD_JOIN_TIMEOUT_MS);
454	      }
455	    } finally {
456	      writeLock.unlock();
457	    }
458	
459	    if (isConfigurationMutable()) {
460	      ((MutableConfigurationProvider) csConfProvider).close();
461	    }
462	    super.serviceStop();
463	  }
