465	  public void reinitialize(Configuration newConf, RMContext rmContext,
466	         boolean validation) throws IOException {
467	    writeLock.lock();
468	    try {
469	      Configuration configuration = new Configuration(newConf);
470	      CapacitySchedulerConfiguration oldConf = this.conf;
471	      if (validation) {
472	        this.conf = new CapacitySchedulerConfiguration(newConf, false);
473	      } else {
474	        this.conf = csConfProvider.loadConfiguration(configuration);
475	      }
476	      validateConf(this.conf);
477	      try {
478	        LOG.info("Re-initializing queues...");
479	        refreshMaximumAllocation(
480	            ResourceUtils.fetchMaximumAllocationFromConfig(this.conf));
481	        reinitializeQueues(this.conf);
482	      } catch (Throwable t) {
483	        this.conf = oldConf;
484	        refreshMaximumAllocation(
485	            ResourceUtils.fetchMaximumAllocationFromConfig(this.conf));
486	        throw new IOException("Failed to re-init queues : " + t.getMessage(),
487	            t);
488	      }
489	      if (!validation) {
490	
491	        // update lazy preemption
492	        this.isLazyPreemptionEnabled = this.conf.getLazyPreemptionEnabled();
493	
494	        // Setup how many containers we can allocate for each round
495	        assignMultipleEnabled = this.conf.getAssignMultipleEnabled();
496	        maxAssignPerHeartbeat = this.conf.getMaxAssignPerHeartbeat();
497	        offswitchPerHeartbeatLimit = this.conf.getOffSwitchPerHeartbeatLimit();
498	        appShouldFailFast = CapacitySchedulerConfiguration.shouldAppFailFast(
499	            getConfig());
500	
501	        LOG.info("assignMultipleEnabled = " + assignMultipleEnabled + "\n" +
502	            "maxAssignPerHeartbeat = " + maxAssignPerHeartbeat + "\n" +
503	            "offswitchPerHeartbeatLimit = " + offswitchPerHeartbeatLimit);
504	
505	        super.reinitialize(newConf, rmContext);
506	      }
507	      maxRunningEnforcer.updateRunnabilityOnReload();
508	    } finally {
509	      writeLock.unlock();
510	    }
511	
512	  }
