653	  static class AsyncScheduleThread extends Thread {
654	
655	    private final CapacityScheduler cs;
656	    private AtomicBoolean runSchedules = new AtomicBoolean(false);
657	
658	    public AsyncScheduleThread(CapacityScheduler cs) {
659	      this.cs = cs;
660	      setName("AsyncCapacitySchedulerThread" + cs.threadNum++);
661	      setDaemon(true);
662	    }
663	
664	    @Override
665	    public void run() {
666	      int debuggingLogCounter = 0;
667	      while (!Thread.currentThread().isInterrupted()) {
668	        try {
669	          if (!runSchedules.get()) {
670	            Thread.sleep(100);
671	          } else {
672	            // Don't run schedule if we have some pending backlogs already
673	            if (cs.getAsyncSchedulingPendingBacklogs()
674	                > cs.asyncMaxPendingBacklogs) {
675	              Thread.sleep(1);
676	            } else{
677	              schedule(cs);
678	              if(LOG.isDebugEnabled()) {
679	                // Adding a debug log here to ensure that the thread is alive
680	                // and running fine.
681	                if (debuggingLogCounter++ > 10000) {
682	                  debuggingLogCounter = 0;
683	                  LOG.debug("AsyncScheduleThread[" + getName() + "] is running!");
684	                }
685	              }
686	            }
687	          }
688	        } catch (InterruptedException ie) {
689	          // keep interrupt signal
690	          Thread.currentThread().interrupt();
691	        }
692	      }
693	      LOG.info("AsyncScheduleThread[" + getName() + "] exited!");
694	    }
695	
696	    public void beginSchedule() {
697	      runSchedules.set(true);
698	    }
699	
700	    public void suspendSchedule() {
701	      runSchedules.set(false);
702	    }
703	
704	  }
