706	  static class ResourceCommitterService extends Thread {
707	    private final CapacityScheduler cs;
708	    private BlockingQueue<ResourceCommitRequest<FiCaSchedulerApp, FiCaSchedulerNode>>
709	        backlogs = new LinkedBlockingQueue<>();
710	
711	    public ResourceCommitterService(CapacityScheduler cs) {
712	      this.cs = cs;
713	      setDaemon(true);
714	    }
715	
716	    @Override
717	    public void run() {
718	      while (!Thread.currentThread().isInterrupted()) {
719	        try {
720	          ResourceCommitRequest<FiCaSchedulerApp, FiCaSchedulerNode> request =
721	              backlogs.take();
722	          cs.writeLock.lock();
723	          try {
724	            cs.tryCommit(cs.getClusterResource(), request, true);
725	          } finally {
726	            cs.writeLock.unlock();
727	          }
728	
729	        } catch (InterruptedException e) {
730	          LOG.error(e.toString());
731	          Thread.currentThread().interrupt();
732	        }
733	      }
734	      LOG.info("ResourceCommitterService exited!");
735	    }
736	
737	    public void addNewCommitRequest(
738	        ResourceCommitRequest<FiCaSchedulerApp, FiCaSchedulerNode> proposal) {
739	      backlogs.add(proposal);
740	    }
741	
742	    public int getPendingBacklogs() {
743	      return backlogs.size();
744	    }
745	  }
